# calculate_wav_dual_entropy.py  (linear 0–1 spectrogram version)# ================================================================="""Visualizer for quality control checks of the combined amplitude, periodicity,and dual entropy song detectors for .wav files.This will take in the .json  file output by wav_feature_extraction_pipeline.pythen generate 1-minute long segments of the detected song. It will highlightdetected song intervals with the following color codes:    - yellow = amplitude detected song segments    - pink = periodicity detected song segments    - blue = entropy detected song segmentsIt then saves .png image files of the detected song. IT ONLY VISUALIZESRECORDINGS THAT CONTAIN PERIODICITY-DETECTED SONGS!!!"""from pathlib import Pathanimal_id      = "R10"     # shown in the output filenamesrecording_date = "2023-05-23"  # YYYY‑MM‑DD              ↑# absolute **or** relative path to the folder that holds the .wav filesfolder_path = Path(    "/Volumes/my_own_SSD/UO_stuff/RC12_R10_Comp1/36")# absolute **or** relative path to the JSON file with detected intervalsjson_path = Path(    "/Volumes/my_own_SSD/UO_stuff/RC12_R10_Comp1/36_periodicity_only_detected_song_intervals_combined_segments.json")#!/usr/bin/env python# -*- coding: utf‑8 -*-"""Split one or more long .wav recordings into consecutive 60‑second clipsand keep track of (1) which original file(s) contributed to each clip and(2) where song was detected inside each clip.The output clips are named:    <animal_id>_<recording_date>_detected_song_segment_<N>.wavand a JSON file `segment_metadata.json` is written alongside them."""import os, jsonimport numpy as npfrom scipy.io import wavfilefrom pathlib import Path   # (unused here, but handy for future tweaks)# ╔══════════════════════════════════════════════════════════════════════╗# CONFIG –– update the four values below# ╚══════════════════════════════════════════════════════════════════════╝# folder_path   = "/Volumes/my_own_SSD/UO_stuff/nerve_transections/USA5207/33"        # directory with raw .wav files# json_path     = "/Volumes/my_own_SSD/UO_stuff/nerve_transections/USA5207/33_periodicity_only_detected_song_intervals_combined_segments.json"      # detector output (song intervals)# animal_id     = 'USA5207'                          # e.g. 'USA5207'# recording_date = '2025-07-19'                      # e.g. 'YYYY‑MM‑DD'# ── derived paths ──────────────────────────────────────────────────────output_folder        = os.path.join(folder_path, 'detected_song_files_full_recordings')os.makedirs(output_folder, exist_ok=True)metadata_output_path = os.path.join(output_folder, 'segment_metadata.json')# ╔══════════════════════════════════════════════════════════════════════╗# LOAD detector JSON  →  {wav_file : [[start,end], …]}# ╚══════════════════════════════════════════════════════════════════════╝with open(json_path, 'r') as f:    detected_intervals = json.load(f)# deterministic processing orderfile_names = sorted(detected_intervals.keys())# ╔══════════════════════════════════════════════════════════════════════╗# READ all wavs into memory (could be streamed if very large files)# ╚══════════════════════════════════════════════════════════════════════╝audio_queue           = []      # list of tuples (file_name, mono_float32_data)sample_rate_reference = Nonefor fn in file_names:    wav_path = os.path.join(folder_path, fn)    if not os.path.exists(wav_path):        print(f"⚠️  Missing file: {fn}")        continue    try:        sr, data = wavfile.read(wav_path)        if sample_rate_reference is None:            sample_rate_reference = sr        elif sr != sample_rate_reference:            raise ValueError(f"Sample‑rate mismatch in {fn} ({sr} vs {sample_rate_reference})")        # stereo → mono        if data.ndim > 1:            data = data.mean(axis=1)        audio_queue.append((fn, data.astype(np.float32)))    except Exception as e:        print(f"⚠️  Error reading {fn}: {e}")if not audio_queue:    raise RuntimeError("No audio files were loaded successfully.")# ╔══════════════════════════════════════════════════════════════════════╗# CHUNKING variables & helpers# ╚══════════════════════════════════════════════════════════════════════╝minute_samples      = 60 * sample_rate_referenceleftover            = np.array([], dtype=np.float32)leftover_provenance = []      # list of dicts: {"source_file", "range_start", "range_end"}segment_metadata    = {}chunk_count         = 0def get_song_segments_within_range(source_file, range_start, range_end):    """Return detector intervals (sec) that overlap [range_start, range_end) in sample    coordinates, expressed relative to the *start* of that range."""    out = []    for t_start, t_end in detected_intervals.get(source_file, []):        s_start = int(t_start * sample_rate_reference)        s_end   = int(t_end   * sample_rate_reference)        ov_start = max(s_start, range_start)        ov_end   = min(s_end,   range_end)        if ov_start < ov_end:            out.append([                round((ov_start - range_start) / sample_rate_reference, 3),                round((ov_end   - range_start) / sample_rate_reference, 3)            ])    return outdef finalize_chunk(chunk_data, provenance, song_segments, idx,                   animal_id, recording_date):    """Write one 60‑s clip to disk and log its metadata."""    fname = (        f"{animal_id}_{recording_date}_detected_song_segment_{idx+1}.wav"    )    fpath = os.path.join(output_folder, fname)    # ensure int16 range    chunk_int16 = np.clip(chunk_data, -32768, 32767).astype(np.int16)    wavfile.write(fpath, sample_rate_reference, chunk_int16)    segment_metadata[fname] = {        "source_files": provenance,        "song_segments_in_chunk": song_segments    }    print(f"✅  Saved {fname}")# ╔══════════════════════════════════════════════════════════════════════╗# MAIN loop –– stitch files, slice 60‑s chunks, preserve provenance# ╚══════════════════════════════════════════════════════════════════════╝for file_name, data in audio_queue:    # 1) build new "combined" buffer = leftover + current file    combined        = np.concatenate([leftover, data])    combined_ranges = []          # [{"source_file", "range_start", "range_end"}]    offset          = 0    # carry forward *all* leftover provenance    for prov in leftover_provenance:        dur = prov["range_end"] - prov["range_start"]        combined_ranges.append({            "source_file": prov["source_file"],            "range_start": offset,            "range_end":   offset + dur        })        offset += dur    # append current file’s span    combined_ranges.append({        "source_file": file_name,        "range_start": offset,        "range_end":   offset + len(data)    })    # 2) slice full‑minute chunks    cursor = 0    while cursor + minute_samples <= len(combined):        chunk               = combined[cursor:cursor + minute_samples]        chunk_provenance    = []        chunk_song_segments = []        chunk_start = cursor        chunk_end   = cursor + minute_samples        for rng in combined_ranges:            src_start, src_end = rng["range_start"], rng["range_end"]            ov_start = max(chunk_start, src_start)            ov_end   = min(chunk_end,   src_end)            if ov_start < ov_end:   # overlap exists                # provenance entry                rel_start_sec = (ov_start - chunk_start) / sample_rate_reference                rel_end_sec   = (ov_end   - chunk_start) / sample_rate_reference                chunk_provenance.append({                    "source_file": rng["source_file"],                    "time_range_in_chunk_seconds": [                        round(rel_start_sec, 3),                        round(rel_end_sec,   3)                    ]                })                # song segments within this overlap                slice_rel_start = ov_start - src_start                slice_rel_end   = ov_end   - src_start                for seg in get_song_segments_within_range(                        rng["source_file"], slice_rel_start, slice_rel_end):                    chunk_song_segments.append([                        round(seg[0] + rel_start_sec, 3),                        round(seg[1] + rel_start_sec, 3)                    ])        finalize_chunk(chunk, chunk_provenance, chunk_song_segments,                       chunk_count, animal_id, recording_date)        chunk_count += 1        cursor      += minute_samples    # 3) whatever is left (< 60 s) → carry to next iteration    leftover = combined[cursor:]    leftover_provenance = []    if len(leftover) > 0:        for rng in combined_ranges:            if rng["range_end"] > cursor:      # part survives                leftover_provenance.append({                    "source_file": rng["source_file"],                    "range_start": max(0, rng["range_start"] - cursor),                    "range_end":   rng["range_end"] - cursor                })# ╔══════════════════════════════════════════════════════════════════════╗# FINAL (possibly padded) chunk made from leftover audio# ╚══════════════════════════════════════════════════════════════════════╝if len(leftover) > 0:    padded = np.pad(        leftover, (0, minute_samples - len(leftover)),        mode="constant"    )    final_prov, final_segs = [], []    for rng in leftover_provenance:        p_start_sec = rng["range_start"] / sample_rate_reference        p_end_sec   = rng["range_end"]   / sample_rate_reference        final_prov.append({            "source_file": rng["source_file"],            "time_range_in_chunk_seconds": [                round(p_start_sec, 3),                round(p_end_sec,   3)            ]        })        for seg in get_song_segments_within_range(                rng["source_file"], 0, rng["range_end"] - rng["range_start"]):            final_segs.append([                round(seg[0] + p_start_sec, 3),                round(seg[1] + p_start_sec, 3)            ])    finalize_chunk(padded, final_prov, final_segs,                   chunk_count, animal_id, recording_date)# ╔══════════════════════════════════════════════════════════════════════╗# WRITE master metadata file# ╚══════════════════════════════════════════════════════════════════════╝with open(metadata_output_path, 'w') as f:    json.dump(segment_metadata, f, indent=2)print(f"📄  Metadata saved to: {metadata_output_path}")#!/usr/bin/env python# -*- coding: utf-8 -*-"""Batch‑render spectrograms for detected‑song minute clips and (re)name theclips themselves with a clearer convention:    <animal_id>_<recording_date>_detected_song_file_minute_<n>.wav"""import os, jsonfrom pathlib import Pathfrom typing import List, Tupleimport numpy as npimport matplotlib.pyplot as pltfrom scipy.io import wavfilefrom scipy.signal import spectrogram, windows, ellip, filtfiltimport tkinter as tk# ────────────────────────────────────────────────────────────────# variables `animal_id`, `recording_date`, `folder_path`, `json_path`# were defined in a previous notebook cell# ────────────────────────────────────────────────────────────────# ────────────────────────────────────────────────────────────────# PATHS  –– join with `/` instead of `+`# ────────────────────────────────────────────────────────────────base_folder    = folder_path / "detected_song_files_full_recordings"   # ← FIXEDspectrogram_out = base_folder / "spectrograms"spectrogram_out.mkdir(exist_ok=True)# Optional metadata JSONmetadata_json = base_folder / "segment_metadata.json"if metadata_json.is_file():    with metadata_json.open("r", encoding="utf-8") as f:        segment_metadata = json.load(f)else:    segment_metadata = {}# ────────────────────────────────────────────────────────────────# Figure‑size helper# ────────────────────────────────────────────────────────────────def get_screen_inches() -> Tuple[float, float]:    try:        root = tk.Tk(); root.withdraw()        w, h = root.winfo_screenwidth(), root.winfo_screenheight()        root.destroy()        return w / 100, h / 100    except Exception:        return 12, 8width_inches, height_inches = get_screen_inches()# ────────────────────────────────────────────────────────────────# Spectrogram rendering for one clip# ────────────────────────────────────────────────────────────────def render_clip(    wav_path: Path,    segment_duration: int = 10,    panels_per_fig: int = 6,    low_cut: int = 500,    high_cut: int = 8000,) -> None:    base_name = wav_path.stem    sr, data  = wavfile.read(wav_path)    if data.ndim > 1:        data = data.mean(axis=1)    if np.issubdtype(data.dtype, np.integer):        data = data.astype(np.float32)    # band‑pass    nyq = sr / 2    b, a = ellip(5, 0.2, 40, [low_cut / nyq, high_cut / nyq], btype="band")    data = filtfilt(b, a, data)    total_secs        = data.size / sr    samples_per_panel = int(segment_duration * sr)    n_panels          = min(panels_per_fig, int(np.ceil(total_secs / segment_duration)))    # annotations    meta_key       = wav_path.name    song_intervals = segment_metadata.get(meta_key, {}).get("song_segments_in_chunk", [])    boundary_lines = [        src["time_range_in_chunk_seconds"][1]        for src in segment_metadata.get(meta_key, {}).get("source_files", [])        if "time_range_in_chunk_seconds" in src    ]    fig, axs = plt.subplots(        n_panels, 1, figsize=(width_inches, height_inches),        sharex=True, gridspec_kw={"hspace": 0.0}    )    axs = [axs] if n_panels == 1 else axs    for idx in range(n_panels):        start_sample = idx * samples_per_panel        panel = data[start_sample : start_sample + samples_per_panel]        if panel.size < samples_per_panel:                 # zero‑pad last panel            panel = np.pad(panel, (0, samples_per_panel - panel.size))        f, t, Sxx = spectrogram(            panel, fs=sr,            window=windows.gaussian(2048, std=2048 / 8),            nperseg=2048, noverlap=2048 - 119,        )        S_log  = 10 * np.log10(Sxx + np.finfo(float).eps)        S_log  = np.clip(S_log, a_min=3, a_max=None)        S_norm = (S_log - S_log.min()) / (S_log.ptp() or 1)        S_norm **= 0.7        axs[idx].imshow(            S_norm, aspect="auto", origin="lower",            extent=[0, segment_duration, f.min(), f.max()],            cmap="binary",        )        axs[idx].set_ylim(0, 11_000)        axs[idx].set_ylabel("Freq [Hz]")        # yellow song spans        p0, p1 = idx * segment_duration, (idx + 1) * segment_duration        for s0, s1 in song_intervals:            if s0 < p1 and s1 > p0:                x0, x1 = max(0, s0 - p0), min(segment_duration, s1 - p0)                axs[idx].axvspan(x0, x1, color="yellow", alpha=0.1)        # (If you removed red boundaries earlier, delete this block.)        for b in boundary_lines:            if p0 < b < p1:                axs[idx].axvline(b - p0, color="red", linestyle="--", linewidth=1.2)        if idx == n_panels - 1:            axs[idx].set_xlabel("Time [s]")            axs[idx].set_xticks(np.linspace(0, segment_duration, 5))    fig.suptitle(f"{base_name} – Spectrogram ({low_cut}-{high_cut} Hz)", fontsize=14)    fig.tight_layout()    out_png = spectrogram_out / f"{base_name}_spectrogram.png"    fig.savefig(out_png, dpi=300)    plt.close(fig)    print(f"✅ spectrogram → {out_png.name}")# ────────────────────────────────────────────────────────────────# Batch rename clips, update metadata map, and render# ────────────────────────────────────────────────────────────────wav_files: List[Path] = sorted(base_folder.glob("*.wav"))if not wav_files:    raise FileNotFoundError(f"No .wav clips found in {base_folder}")print(f"\n📂 Found {len(wav_files)} clips – renaming & rendering …\n")for idx, old_path in enumerate(wav_files, start=1):    new_name = f"{animal_id}_{recording_date}_detected_song_file_minute_{idx}.wav"    new_path = old_path.with_name(new_name)    if old_path.name != new_name:           # rename on disk        old_path.rename(new_path)    # keep metadata mapping in sync    if old_path.name in segment_metadata and new_name not in segment_metadata:        segment_metadata[new_name] = segment_metadata[old_path.name]    render_clip(new_path)print("\nDone!  Spectrograms in:", spectrogram_out.resolve())